import json,re
T=json.load(open('data/cache/9b676d7031b1bcd3b8377a18.docs.json'))[0]['text']
A,B=168259,171385
U=T[A:B]
d=json.load(open('loop/state/out/read_dafeng_L3_0055.candidate.json'))
cov=[False]*(B-A)
def walk(o):
    if isinstance(o,dict):
        if 'quote' in o and 'start' in o and 'end' in o and o.get('inUnitRange'):
            for i in range(max(o['start'],A),min(o['end'],B)): cov[i-A]=True
            return
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(d)
han=re.compile(r'[\u4e00-\u9fff]')
spans=[];i=0
while i<len(U):
    if not cov[i]:
        j=i
        while j<len(U) and not cov[j]: j+=1
        spans.append((i,j)); i=j
    else: i+=1
content=[(A+s,A+e,U[s:e]) for s,e in spans if han.search(U[s:e])]
print('covered %d/%d = %.2f%%'%(sum(cov),len(U),100*sum(cov)/len(U)))
print('maximal uncovered runs',len(spans),'| runs with Han',len(content),
      '| uncovered Han chars',sum(len(han.findall(U[s:e])) for s,e in spans))
for a,b,t in content: print('  @[%d,%d) han=%d %r'%(a,b,len(han.findall(t)),t))
